# Derive the QoS class from requests and limits (cpu, memory in simple units).
def qos(containers):
    anything_set = any(c.get("req") or c.get("lim") for c in containers)
    if not anything_set:
        return "BestEffort"  # nothing set at all
    for c in containers:
        req, lim = c.get("req", {}), c.get("lim", {})
        # Guaranteed: cpu and memory set, request == limit, in every container
        if not all(k in req and k in lim and req[k] == lim[k] for k in ("cpu", "memory")):
            return "Burstable"
    return "Guaranteed"

cases = {
    "no resources": [{}],
    "request only": [{"req": {"cpu": 100, "memory": 128}}],
    "equal req/lim": [{"req": {"cpu": 500, "memory": 256}, "lim": {"cpu": 500, "memory": 256}}],
    "memory equal, cpu no limit": [{"req": {"cpu": 200, "memory": 256}, "lim": {"memory": 256}}],
}
for name, cs in cases.items():
    print(f"{name:28} -> {qos(cs)}")
# Under node memory pressure the kubelet evicts BestEffort first, Guaranteed last.

# Scheduler fit check: sum of REQUESTS (not real usage) must fit the node's free capacity.
nodes = {"node-a": {"cpu": 4000, "mem": 8192, "taint": None},
         "node-b": {"cpu": 4000, "mem": 8192, "taint": "gpu"}}
placed = {"node-a": [(3500, 2000)], "node-b": []}   # (cpu m, mem Mi) already requested

def why_pending(pod):
    reasons = []
    for n, cap in nodes.items():
        if cap["taint"] and cap["taint"] not in pod["tolerations"]:
            reasons.append(f"{n}: untolerated taint {cap['taint']}")
            continue
        used_cpu = sum(c for c, _ in placed[n])
        used_mem = sum(m for _, m in placed[n])
        if used_cpu + pod["cpu"] > cap["cpu"]:
            reasons.append(f"{n}: Insufficient cpu ({used_cpu}+{pod['cpu']} > {cap['cpu']})")
        elif used_mem + pod["mem"] > cap["mem"]:
            reasons.append(f"{n}: Insufficient memory")
        else:
            return f"scheduled on {n}"
    return "Pending: " + "; ".join(reasons)

print("Pod asks 1000m cpu:", why_pending({"cpu": 1000, "mem": 512, "tolerations": []}))
print("Pod asks 500m cpu :", why_pending({"cpu": 500, "mem": 512, "tolerations": []}))
